for name,u in urls.items():
    d=zlib.decompressobj(16+zlib.MAX_WBITS)
    out=b''
    with requests.get(u, stream=True, timeout=120) as r:
        for chunk in r.iter_content(chunk_size=500000):
            out += d.decompress(chunk)
            if out.count(b'\\n')>2: break
    text=out.decode(errors='replace')
    lines=text.splitlines()
    print('====',name,'====')
    # print all header lines and first data line if any
    for i,line in enumerate(lines[:100]):
        if line.startswith('#'):
            print(line[:1000])
        else:
            print('DATA line', i, 'tabs', line.count('\\t'), 'first', line[:2000])
            break
